-- 02_backfill_from_weather_regular.sql
-- Backfill: aggregates every day in weather_regular and appends to
-- weather_daily. Many columns come out NULL because weather_regular
-- doesn't record them (cs320_irradiance, solar flux, strikes, etc.).
--
-- !!! AUTOGENERATED by daily_conversion/render_sql.py !!!
-- Do not edit this file directly. Edit the config at the top of
-- render_sql.py (SOURCES / AGGS / VARIABLES) and re-run:
--     python daily_conversion/render_sql.py

INSERT INTO weather_daily (
    date,
    atmospheric_pressure_mean,
    atmospheric_pressure_max,
    atmospheric_pressure_min,
    cs320_irradiance_mean,
    cs320_irradiance_max,
    cs320_irradiance_min,
    cs320_irradiance_sum,
    cs320_irradiance_count_gt_5,
    cs320_irradiance_gt_5_mean,
    cs320_irradiance_bright_count,
    dewpoint_temp_min,
    dewpoint_temp_max,
    dewpoint_temp_mean,
    dist_min,
    humidity_mean,
    humidity_min,
    humidity_max,
    precipdrop_sum,
    precipitation_sum,
    precipitation_count,
    precipitation_count_gt_0,
    precipitation_intensity_mean,
    solar_flux_density_wm2_mean,
    solar_flux_density_wm2_max,
    solar_flux_density_wm2_min,
    solar_flux_density_wm2_sum,
    solar_flux_density_wm2_count_gt_5,
    solar_flux_density_wm2_gt_5_mean,
    solar_flux_density_wm2_bright_count,
    uvb_radiation_mean,
    uvb_radiation_max,
    uvb_radiation_min,
    uvb_radiation_sum,
    uvb_radiation_count_gt_5,
    uvb_radiation_gt_5_mean,
    uvb_radiation_bright_count,
    uva_radiation_mean,
    uva_radiation_max,
    uva_radiation_min,
    uva_radiation_sum,
    uva_radiation_count_gt_5,
    uva_radiation_gt_5_mean,
    uva_radiation_bright_count,
    strikes_sum,
    temperature_min,
    temperature_max,
    temperature_mean,
    temperature_diurnal_range,
    temperature_count_below_0,
    temperature_count_below_5,
    temperature_count_above_30,
    temperature_count_above_35,
    temperature_count_above_40,
    wind_speed_min,
    wind_speed_max,
    wind_speed_mean,
    wind_speed_count_gt_14,
    wind_speed_count_gt_21,
    vp_mean,
    vp_min,
    vp_max,
    vp_diurnal_range,
    valid_count,
    data_availability
)
SELECT
    timestamp::date AS date,
    AVG(atmospheric_pressure) AS atmospheric_pressure_mean,
    MAX(atmospheric_pressure) AS atmospheric_pressure_max,
    MIN(atmospheric_pressure) AS atmospheric_pressure_min,
    NULL::double precision AS cs320_irradiance_mean,
    NULL::double precision AS cs320_irradiance_max,
    NULL::double precision AS cs320_irradiance_min,
    NULL::double precision AS cs320_irradiance_sum,
    NULL::integer AS cs320_irradiance_count_gt_5,
    NULL::double precision AS cs320_irradiance_gt_5_mean,
    NULL::integer AS cs320_irradiance_bright_count,
    MIN(dewpoint_temp) AS dewpoint_temp_min,
    MAX(dewpoint_temp) AS dewpoint_temp_max,
    AVG(dewpoint_temp) AS dewpoint_temp_mean,
    NULL::double precision AS dist_min,
    AVG(humidity) AS humidity_mean,
    MIN(humidity) AS humidity_min,
    MAX(humidity) AS humidity_max,
    NULL::double precision AS precipdrop_sum,
    SUM(precipitation) AS precipitation_sum,
    COUNT(precipitation) FILTER (WHERE precipitation IS NOT NULL) AS precipitation_count,
    COUNT(*) FILTER (WHERE precipitation > 0) AS precipitation_count_gt_0,
    NULL::double precision AS precipitation_intensity_mean,
    NULL::double precision AS solar_flux_density_wm2_mean,
    NULL::double precision AS solar_flux_density_wm2_max,
    NULL::double precision AS solar_flux_density_wm2_min,
    NULL::double precision AS solar_flux_density_wm2_sum,
    NULL::integer AS solar_flux_density_wm2_count_gt_5,
    NULL::double precision AS solar_flux_density_wm2_gt_5_mean,
    NULL::integer AS solar_flux_density_wm2_bright_count,
    AVG(NULLIF(uvb_radiation, -1)) AS uvb_radiation_mean,
    MAX(NULLIF(uvb_radiation, -1)) AS uvb_radiation_max,
    MIN(NULLIF(uvb_radiation, -1)) AS uvb_radiation_min,
    SUM(NULLIF(uvb_radiation, -1)) AS uvb_radiation_sum,
    COUNT(*) FILTER (WHERE NULLIF(uvb_radiation, -1) > 5) AS uvb_radiation_count_gt_5,
    AVG(NULLIF(uvb_radiation, -1)) FILTER (WHERE NULLIF(uvb_radiation, -1) > 5) AS uvb_radiation_gt_5_mean,
    COUNT(*) FILTER (WHERE NULLIF(uvb_radiation, -1) > 10) AS uvb_radiation_bright_count,
    AVG(NULLIF(uvb_radiation2, -1)) AS uva_radiation_mean,
    MAX(NULLIF(uvb_radiation2, -1)) AS uva_radiation_max,
    MIN(NULLIF(uvb_radiation2, -1)) AS uva_radiation_min,
    SUM(NULLIF(uvb_radiation2, -1)) AS uva_radiation_sum,
    COUNT(*) FILTER (WHERE NULLIF(uvb_radiation2, -1) > 5) AS uva_radiation_count_gt_5,
    AVG(NULLIF(uvb_radiation2, -1)) FILTER (WHERE NULLIF(uvb_radiation2, -1) > 5) AS uva_radiation_gt_5_mean,
    COUNT(*) FILTER (WHERE NULLIF(uvb_radiation2, -1) > 10) AS uva_radiation_bright_count,
    NULL::integer AS strikes_sum,
    MIN(temperature) AS temperature_min,
    MAX(temperature) AS temperature_max,
    AVG(temperature) AS temperature_mean,
    MAX(temperature) - MIN(temperature) AS temperature_diurnal_range,
    COUNT(*) FILTER (WHERE temperature < 0) AS temperature_count_below_0,
    COUNT(*) FILTER (WHERE temperature < 5) AS temperature_count_below_5,
    COUNT(*) FILTER (WHERE temperature > 30) AS temperature_count_above_30,
    COUNT(*) FILTER (WHERE temperature > 35) AS temperature_count_above_35,
    COUNT(*) FILTER (WHERE temperature > 40) AS temperature_count_above_40,
    MIN(wind_speed) AS wind_speed_min,
    MAX(wind_speed) AS wind_speed_max,
    AVG(wind_speed) AS wind_speed_mean,
    COUNT(*) FILTER (WHERE wind_speed > 14) AS wind_speed_count_gt_14,
    COUNT(*) FILTER (WHERE wind_speed > 21) AS wind_speed_count_gt_21,
    NULL::double precision AS vp_mean,
    NULL::double precision AS vp_min,
    NULL::double precision AS vp_max,
    NULL::double precision AS vp_diurnal_range,
    COUNT(*) AS valid_count,
    COUNT(*)::double precision / 1440 AS data_availability
FROM weather_regular
GROUP BY timestamp::date
ON CONFLICT (date) DO NOTHING;
